mkdir -p artifacts && node -e '
const fs=require("fs");
const data=JSON.parse(fs.readFileSync("inputs/invoices.json","utf8"));
const byId=new Map();
for(const inv of data){
  const cur=byId.get(inv.id);
  if(!cur||inv.revision>cur.revision) byId.set(inv.id,inv);
}
let includedInvoices=0,voidInvoices=0,supersededRows=0;
const groups=new Map();
for(const inv of data){
  const top=byId.get(inv.id);
  if(inv!==top) supersededRows++;
}
for(const inv of byId.values()){
  if(inv.status==="void"){voidInvoices++;continue;}
  includedInvoices++;
  const key=inv.customer+"\u0000"+inv.currency;
  if(!groups.has(key)) groups.set(key,{customer:inv.customer,currency:inv.currency,netCents:0,count:0});
  const g=groups.get(key);
  g.count++;
  g.netCents+= inv.status==="refunded" ? -inv.amountCents : inv.amountCents;
}
const rows=[...groups.values()].sort((a,b)=>a.customer<b.customer?-1:a.customer>b.customer?1:a.currency<b.currency?-1:a.currency>b.currency?1:0);
const report={rows,includedInvoices,voidInvoices,supersededRows};
fs.writeFileSync("artifacts/report.json",JSON.stringify(report,null,2)+"\n");
'

node -e '
const fs=require("fs");
const r=JSON.parse(fs.readFileSync("artifacts/report.json","utf8"));
const keys=Object.keys(r).sort().join(",");
if(keys!=="includedInvoices,rows,supersededRows,voidInvoices") throw new Error("bad top-level keys: "+keys);
const exp=[
 {customer:"Acme",currency:"EUR",netCents:500,count:1},
 {customer:"Acme",currency:"USD",netCents:950,count:2},
 {customer:"Beta",currency:"EUR",netCents:-75,count:1},
 {customer:"Beta",currency:"USD",netCents:300,count:1},
 {customer:"Gamma",currency:"USD",netCents:0,count:1}
];
if(JSON.stringify(r.rows)!==JSON.stringify(exp)) throw new Error("rows mismatch: "+JSON.stringify(r.rows));
if(r.includedInvoices!==6) throw new Error("includedInvoices="+r.includedInvoices);
if(r.voidInvoices!==1) throw new Error("voidInvoices="+r.voidInvoices);
if(r.supersededRows!==2) throw new Error("supersededRows="+r.supersededRows);
console.log("report verified");
'
